#include <iostream>
#include <string>
#include <typeinfo>
using namespace std;

class Cat {
public:
    string name;
    Cat(const string& n) : name(n) {}
    virtual ~Cat() {}
};

class OrangeCat : public Cat {
public:
    OrangeCat(const string& n) : Cat(n) {}
};

class TabbyCat : public Cat {
public:
    TabbyCat(const string& n) : Cat(n) {}
};

int main() {
    int kind = 0;
    cin >> kind;

    OrangeCat o("{who}");
    TabbyCat t("{other}");
    Cat* p = &t;
    if (kind == 1) p = &o;

    try {
        OrangeCat& r = dynamic_cast<OrangeCat&>(*p);
        cout << "照出来了：" << r.name << endl;
    } catch (const bad_cast& e) {
        cout << "照不出来：" << e.what() << endl;
    }
    return 0;
}
